head.script:
 
        var tmpFundGb  =  '';
		var tmpMngScl  =  '';
		var tmpCdList    =  '';
		var uDivisionId1 = '';
		var uDivisionId2 = '';
		var uDivisionId3 = '';
        var now = getToday();
        var codeDescNm = "";
		var codeTitleNm = "";
		var codeValueCh = "";
		var pCd1,pCd2,pCd3,pCd2Idx=3;
		
        /**************************************************************************
		 * function    : initRopCmpAnn
		 * Description : 펀드수익률 비교공시 UI 생성 기본 함수
		 * Parameter   : null
		 * Return      : null
		 **************************************************************************/
        function initRopCmpAnn() {
        	centerContainer();
			$(window).on('resize', function(){
				btnContainerResize('return');
				centerContainer();
			});
			
			var inServiceId = vServiceId;
			if (inServiceId == '')
				inServiceId = 'SDIS01009001000';
		
			callGnb(vDivisionId);
			callSnb(vDivisionId);
			callDisService(vDivisionId);
			
			callUi();
			
			addDisUserLog(vDivisionId, inServiceId);
			
			pCd1 = WebSquare.net.getParameter( "pCd1");
			pCd2 = WebSquare.net.getParameter( "pCd2");
			pCd3 = WebSquare.net.getParameter( "pCd3");
			
			if (now.substring(0,4) > '2009')
				initCond();
        }
        
         /**************************************************************************
		 * function    : initCond
		 * Description : 조건부 setting
		 * Parameter   : null
		 * Return      : null
		 **************************************************************************/
        function initCond() {
			pCd2Idx = 3;

        	setStandardDt("Y", returnStandardDt);
        	
        	function returnStandardDt() {
        		setStandardDt("M",returnMonth);
        		
        		setCommonCd('fundType','T1100');
        		initListCheck();
        		changePcd2();
        	}
        	function returnMonth(){
       			//alert(uMonth.getItemCount());
       			var monLength = uMonth.getItemCount();
       			uMonth.setSelectedIndex(monLength-1);
				changePcd2();
       		}
       		
         	setCommonCd('tblList4','T1204', setBranchNm);
         	function setBranchNm() {
         		changeSel7(vBranchCd1.getValue(), vBranchNm1.getValue()) ;
				changePcd2();
         	}

			
  	    }
        
		
		function changePcd2() {
			if (pCd2Idx == 0)
			{
				pCd2= "";
			}

			pCd2Idx--;
		}

        /**************************************************************************
		 * function    : resetCond
		 * Description : 조건부 초기화
		 * Parameter   : null
		 * Return      : null
		 **************************************************************************/
        function resetCond() {
        	radioBtnClear();
        	initCond();
        }
        
        /**************************************************************************
		 * function    : setNewMngResBrn
		 * Description : 운용실적2차조회 세팅
		 * Parameter   : null
		 * Return      : null
		 **************************************************************************/
        function changeSel7(firstCode,firstNm){	
			vBranchNm1.setValue( firstNm );
			vBranchCd1.setValue( firstCode );

			tblList4tit.setLabel('[' + firstNm + ']');
			tblList4Desc.setValue(firstNm);
			setNewMngResBrn("S","tblList5",firstCode, returnCallback);
			
			function returnCallback() {
				setNewMngResBrn("T","tblList6",codeValueCh);
			}
			
		}

		var selId;
		/**************************************************************************
		 * function    : setNewMngResBrn
		 * Description : 운용실적2차조회 세팅
		 * Parameter   : null
		 * Return      : null
		 **************************************************************************/
        function setNewMngResBrn(option,id,codeValue, callback) {
        	
        	var inDTO  = {"DISMngResBrnListDTO":{}}
        	
        	CallProFrame.insertValue(inDTO,"option",option);	
			CallProFrame.insertValue(inDTO,"code",codeValue);	
 			CallProFrame.callService("FS-DIS2", "DISMngResBrnSrchSO", "select", inDTO, null,{'success' : getNewMngResBrn});
  			
 			function getNewMngResBrn(e) {
 				var text = "";
 				
 				var resArr = WebSquare.xml.findNodes(e.responseBody,'root/message/DISMngResBrnListDTO/list');
 				
 				if (resArr.length > 0) {
 					var innerValue = "";
 					var chkId = id;
 					
	 				for (var i=0; i < resArr.length ; i++) {
		 				var commonCd = WebSquare.xml.getValue(resArr[i], 'commonCd');
						var codeNm = WebSquare.xml.getValue(resArr[i], 'codeNm');
						var codeDesc = WebSquare.xml.getValue(resArr[i], 'codeDesc');
						var classNm = '';
						
						if (chkId == 'tblList5') {
							if (pCd2) {
								if (pCd2==commonCd) {
									
									classNm = "on";
									codeValueCh = commonCd;
									codeDescNm = codeDesc;
									codeTitleNm = codeNm;
									
									// 첫번째 ROW를 디폴트 선택값으로 셋팅
									vBranchNm2.setValue(codeNm);
									vBranchCd2.setValue(commonCd);
									//pCd2 = "";
								}
							} else {
								if (i==0) {
									
									classNm = "on";
									codeValueCh = commonCd;
									codeDescNm = codeDesc;
									codeTitleNm = codeNm;
									
									// 첫번째 ROW를 디폴트 선택값으로 셋팅
									vBranchNm2.setValue(codeNm);
									vBranchCd2.setValue(commonCd);
								}
							}
							
							innerValue +="<li style=\"cursor:pointer;\"  class=''><a class='" + classNm + "' onClick='selectNextBrn(\"" + commonCd + "\",\"" + codeDesc + "\",\"" + chkId + "\",\"" + codeNm + "\"," + i + ")' >" + codeNm + "</a></li>";
							
							
						} else if (chkId == 'tblList6') {
							if (pCd3)
							{
								if (pCd3 == commonCd) {
									classNm = "on";
									codeValueCh = commonCd;
									codeDescNm = codeDesc;
									codeTitleNm = codeNm;
									
									vBranchNm3.setValue(codeNm);
									vBranchCd3.setValue(commonCd);
									pCd3 = "";
								}
							} else {
								if (i == 0) {
									classNm = "on";
									codeValueCh = commonCd;
									codeDescNm = codeDesc;
									codeTitleNm = codeNm;
									
									vBranchNm3.setValue(codeNm);
									vBranchCd3.setValue(commonCd);
								}
							}
							
							innerValue +="<li style=\"cursor:pointer;\" class=''><a class='" + classNm + "' onClick='selectNextBrn(\"" + commonCd + "\",\"" + codeDesc + "\",\"" + chkId + "\",\"" + codeNm + "\"," + i + ")' >" + codeNm + "</a></li>";
						}
	 				}
	 				
	 				if(chkId =="tblList5") {
	 					document.getElementById("tblList5").innerHTML = innerValue;
						tblList5tit.setLabel('[' + codeTitleNm + ']');
						tblList5Desc.setLabel(codeDescNm);
	 				
	 				} else if (chkId =="tblList6") {
	 					document.getElementById("tblList6").innerHTML = innerValue;
	 					tblList6tit.setLabel('[' + codeTitleNm + ']');
						tblList6Desc.setLabel(codeDescNm);
	 				}
	 			} else {
	 				if (chkId =="tblList5") {
	 					vBranchNm2.setValue('');
						vBranchCd2.setValue('');
	 				} else if (chkId =="tblList6") {
	 					vBranchNm3.setValue('');
						vBranchCd3.setValue('');
	 				}
	 			}
	 			
	 			if (callback)
	 				callback();
	 				
        	}
        }
        
        
        
         /**************************************************************************
		 * function    : setCommonCd
		 * Description : 공통코드 조회
		 * Parameter   : null
		 * Return      : null
		 **************************************************************************/
        function setCommonCd(id,groupCd, callback){
        	var inDTO  = {"DISCommonCdListDTO":{}}
        	
			selId = id;
			
			CallProFrame.insertValue(inDTO, "groupCd", groupCd);
			CallProFrame.callService("FS-DIS2", "DISFundCmpFundComCdSO", "select", inDTO, null,{'success' : getCommonCd});
			
			function getCommonCd(e) {
				var codeTitleNm = "";
				var codeValue = "";
				var chkMonth = uMonth.getValue();
				var chkYear = uYear.getValue();
				
				if (id =="fundType" && (chkYear>2009 ||(chkYear==2009 && chkMonth=="12") ) ) {
					fundType.addItem( 0 , '전체' , 0);
				}	
				
				var commnArr = WebSquare.xml.findNodes(e.responseBody,'/root/message/DISCommonCdListDTO/list');
				for (var i=0; i<commnArr.length; i++) {
					var commonCd = WebSquare.xml.getValue(commnArr[i], 'commonCd');
					var codeNm = WebSquare.xml.getValue(commnArr[i], 'codeNm');
					
					if (id == "fundType") {
						if ( tmpFundGb == commonCd ) {
							fundGb.setValue(tmpFundGb);
						} 
						
						fundType.addItem( commonCd , codeNm , i+1);
					} else if (id =="tblList4") {
						if (i == 0) {
							codeTitleNm = codeNm;
							codeValue = commonCd;
						}
						
						radioBtn.addItem( commonCd , codeNm , i );
					}
					if (id == "fundType") { // 디폴트 선택
						if (fundType.getValue()=="")
						{
							fundType.setSelectedIndex(0);
						}
					}
					
				}
				
				if (id =="tblList4") {
					if (pCd1) {
						radioBtn.setValue(pCd1);
					} else {
						radioBtn.setSelectedIndex(0);	
					}
					tblList4tit.setLabel('[' + codeTitleNm + ']');
					tblList4Desc.setLabel(codeTitleNm);
					
					vBranchNm1.setValue( codeTitleNm );
					vBranchCd1.setValue( codeValue );
				}
				if (callback)
					callback(); 
			}
		}	
        
		/**************************************************************************
		 * function    : initListCheck
		 * Description : 수익률구간 setting
		 * Parameter   : null
		 * Return      : null
		 **************************************************************************/
		function initListCheck() {
			listCheck.setValue("0 2 4 10");
		}
		
		/**************************************************************************
		 * function    : chgSrchArea
		 * Description : 운영실적 분류 UI생성
		 * Parameter   : null
		 * Return      : null
		 **************************************************************************/
		function chgSrchArea(callback) {
			var reYearData = uYear.getValue();
			var vMonthValue = uMonth.getValue();
			reYearData = parseInt(reYearData,10)
			//console.log('reYearData>>>>>>>>>>>>[' + typeof reYearData + '],data>>>>>' + reYearData);
			
			if(reYearData > 2009) {
				$('#11monthBf').hide();
				$('#12monthLt').show();
				$('#11monthMenu').hide();
				$('#12monthMenu').show();
				$('#12monthTitle').show();

				//radioBtnClear();
			} else if(reYearData == 2009) {
				if(vMonthValue == "12") {
					$('#11monthBf').hide();
					$('#12monthLt').show();
					$('#11monthMenu').hide();
					$('#12monthMenu').show();
					$('#12monthTitle').show();
					//radioBtnClear();
				}else{
					$('#11monthBf').show();
					$('#12monthLt').hide();
					$('#11monthMenu').show();
					$('#12monthMenu').hide();
					$('#12monthTitle').hide();
					
					//radioBtnClear();
				}
			} else {
				$('#11monthBf').show();
				$('#12monthLt').hide();
				$('#11monthMenu').show();
				$('#12monthMenu').hide();
				$('#12monthTitle').hide();
				
				//radioBtnClear();
				
			}
			
			if (callback)
				callback();
		}
		
		
	    /**************************************************************************
		 * function    : setStandardDt
		 * Description : 기준일자생성
		 * Parameter   : null
		 * Return      : null
		 **************************************************************************/
	    function setStandardDt(uGb, callback) {
	    	//vGb.setValue(uGb);
			var inDTO  = {"DISComSetStdDtListDTO":{}};
			if(uGb=="M"){
				CallProFrame.insertValue(inDTO, "standardYm", uYear.getValue());
			} 
			
			CallProFrame.insertValue(inDTO, "uGb", uGb);
			CallProFrame.callService("FS-DIS2", "DISComSetStdDtSO", "select", inDTO, null,{'success' : getStandardDt});
	    	
	    	function getStandardDt(e){
				
				var thisYear = now.substring(0,4);
				var thisMonth = now.substring(4,6);
				
				if(uGb =="Y"){
					WebSquare.ModelUtil.setInstanceNode( e.responseBody , "resStdYY", null , "replace" );
					WebSquare.util.getComponentById("uYear").setNodeSet( "resStdYY/root/message/DISComSetStdDtListDTO" , "list/standardDt" , "list/standardDt" );

					var cYear = uYear.getValue();
					var cYearIdx = uYear.getSelectedIndex();
					
					makeYear();
					//setStandardDt('M');
				}else if(uGb =="M"){
					WebSquare.ModelUtil.setInstanceNode( e.responseBody , "resStdMM", null , "replace" );
					WebSquare.util.getComponentById("uMonth").setNodeSet( "resStdMM/root/message/DISComSetStdDtListDTO" , "list/standardDt" , "list/standardDt" );
					
					var cMon = uMonth.getValue();
					var cMonIdx = uMonth.getSelectedIndex();
					
					//uMonth.setSelectedIndex(0);
					//uMonth.setValue(thisMonth);
				}
				
				chgSrchArea();
				
				if (callback)
					callback();
			}
	    }
	    
	    /**************************************************************************
		 * function    : makeYear
		 * Description : 2009년 이전 기준연도 생성
		 * Parameter   : null
		 * Return      : null
		 **************************************************************************/
	    function makeYear(){
			var y = getToday().substring(0,4);
			for(var i=y;i>=1998;i--){
				if(i >= 2009)
				 continue;
				
				uYear.addItem( i , i , uYear.getItemCount());
			}
		}
	    
	    /**************************************************************************
		 * function    : clearSel
		 * Description : 기준월 초기화
		 * Parameter   : null
		 * Return      : null
		 **************************************************************************/
	    function clearSel(objNm){
	    	WebSquare.util.getComponentById(objNm).removeAll(true);
		}
	    
	    /**************************************************************************
		 * function    : radioBtnClear
		 * Description : 라디오버튼 초기화
		 * Parameter   : null
		 * Return      : null
		 **************************************************************************/
	    function radioBtnClear() {
			var chkMonth = uMonth.getValue();
			var chkYear = uYear.getValue();
			
			if( (chkYear==2009 && chkMonth==12) || chkYear > 2009) {
				if ( tmpFundGb == "" || tmpFundGb == null || tmpFundGb == "undefined") {
					//펀드유형초기화
					fundType.removeAll();
				}
			}else{
				if ( tmpFundGb == "" || tmpFundGb == null || tmpFundGb == "undefined") {
					fundType.removeAll();
				}
			}
			
			if ( tmpMngScl == "") {
				//운용규모 초기화
				Imgradio1.setSelectedIndex(0);
			}
			
			//운용실적 1차분류 초기화
			radioBtn.removeAll();	
	    	
	    }
	    
	    /**************************************************************************
		 * function    : changeSel4
		 * Description : 기준월 변경 이벤트 처리
		 * Parameter   : null
		 * Return      : null
		 **************************************************************************/
	    function changeSel4(){
	    	var chkMonth = uMonth.getValue();
			var chkYear = uYear.getValue();
				chkYear = parseInt(chkYear, 10);	
				chkMonth = parseInt(chkMonth, 10);	
				
			chgSrchArea();
			if(chkYear == 2009 || chkYear < 2009) {
				if(chkMonth ==12) {
					radioBtnClear();
					setCommonCd('fundType','T1100');
					setCommonCd('tblList4','T1204');
					tmpFundGb = "";
				} else {
					radioBtnClear();
					setCommonCd('fundType','T1100');
					tmpFundGb = "";
					setFundGbComp(fundCallBack);
					function fundCallBack() {
						setMngResDiv('tblList1');
					}
				}
			} else {
				radioBtnClear();
				setCommonCd('fundType','T1100');
				setCommonCd('tblList4','T1204');
				tmpFundGb = "";
			}
		}
	    
	    
	    /**************************************************************************
		 * function    : changeSel5
		 * Description : 기준연도 변경 이벤트 처리
		 * Parameter   : null
		 * Return      : null
		 **************************************************************************/
	    function changeSel5(){
	    	var uMonth = WebSquare.util.getComponentById("uMonth");
			var yearChk = uYear.getValue();
			var	monthChk = uMonth.getValue();
				yearChk = parseInt(yearChk, 10);
			
			if( yearChk>2009) {
				chgSrchArea();
			    //2010년이후의 월 조회 조건 문제점 해결방안
				
				clearSel('uMonth'); 
				tmpFundGb = "";
				setStandardDt("M");
				setCommonCd('fundType','T1100');
				radioBtnClear();
				setCommonCd('tblList4','T1204');
				var firstCd = vBranchNm1.getValue();
				var codeVal = vBranchCd1.getValue();
				
				setNewMngResBrn("S","tblList5",firstCd);
				setNewMngResBrn("T","tblList6",codeVal);
			} else {
				//makeMonth();
				chgSrchArea();
				clearSel('uMonth'); 
				radioBtnClear();
				setStandardDt("M", innerCallBack);
				
				var firstCd = vBranchNm1.getValue();
				var codeVal = vBranchCd1.getValue();
				
				function innerCallBack() {
					setCommonCd('fundType','T1100');
					tmpFundGb = "";
					
					var yChk = parseInt(yearChk, 10);
					var mChk = parseInt(monthChk, 10);
					
					
					if(yChk==2009 && mChk==12) {
						setCommonCd('tblList4','T1204');
						var firstCode = vBranchCd1.getValue();
						
						setNewMngResBrn("S","tblList5",firstCd);
						setNewMngResBrn("T","tblList6",codeVal);
					}else{
						setFundGbComp(fundCallback);
						function fundCallback() {
							setMngResDiv('tblList1');
						}
					}
				}
			}
			
		}
	    
	    /**************************************************************************
		 * function    : selectNextBrn
		 * Description : 운용실적 분류 이벤트 처리
		 * Parameter   : null
		 * Return      : null
		 **************************************************************************/
	    function selectNextBrn(vCodeVal,vCodeDesc,vSelId,vTitle,vCnt) {
	    	if(vSelId=="tblList5") {
				selChkViewOff(vSelId);
				
				$('#tblList5 a').eq(vCnt).addClass('on');
				
				document.getElementById("tblList5tit").innerHTML ="<b> ["+ vTitle + "]</b>";
				document.getElementById("tblList5Desc").innerText = vCodeDesc;
				document.getElementById("vBranchCd2").value = vCodeVal;
				document.getElementById("vBranchNm2").value = vTitle;
				setNewMngResBrn("T","tblList6",vCodeVal);
			} else if(vSelId=="tblList6") {
				selChkViewOff(vSelId);
				
				$('#tblList6 a').eq(vCnt).addClass('on');
				
				document.getElementById("tblList6tit").innerHTML ="<b> ["+ vTitle + "]</b>";
				document.getElementById("tblList6Desc").innerText = vCodeDesc;
				document.getElementById("vBranchCd3").value = vCodeVal;
				document.getElementById("vBranchNm3").value = vTitle;
			}
	    	
	    }
	    
	    /**************************************************************************
		 * function    : selChkViewOff
		 * Description : 운용실적 분류 체크 변경
		 * Parameter   : null
		 * Return      : null
		 **************************************************************************/
	    function selChkViewOff(vSelIdNm) {
			if(vSelIdNm =="tblList5") {
				$('#tblList5 li a').removeClass('on');
			} else {	
				$('#tblList6 li a').removeClass('on');
			}
				
		}
	    
	    /**************************************************************************
		 * function    : changeSel6
		 * Description : 집합투자업자 변경 이벤트
		 * Parameter   : null
		 * Return      : null
		 **************************************************************************/
	    function changeSel6(){	
			setMngResDiv('tblList1');
		}
	    
	     /**************************************************************************
		 * function    : setMngResDiv
		 * Description : 2009년 12월 이전 운용실적 내용 생성
		 * Parameter   : null
		 * Return      : null
		 **************************************************************************/
		var idDiv;
		var vPriPubGb;
		var dvId;
		var MngResXml;
	    function setMngResDiv(id,uDivCntGb,aDivisionId){
			idDiv = id;
			dvId = aDivisionId;
			
			var standardYm = uYear.getValue() +""+ uMonth.getValue();
			var scompanyCd = companyCd.getValue();
			var spriPubGb = priPubGb.getValue();
			
			vPriPubGb=priPubGb;

			radioCheck();
			var fundGb = ufundTyp.getValue();
			var inDTO  = {"DISMngResDivInputDTO":{}}

			CallProFrame.insertValue(inDTO, "standardYm", standardYm);
			CallProFrame.insertValue(inDTO, "priPubGb", spriPubGb);
			
			if(companyCd !="" || companyCd != null ){		
				CallProFrame.insertValue(inDTO, "companyCd", scompanyCd);
			} 
			
			CallProFrame.insertValue(inDTO, "fundGb", fundGb);
			CallProFrame.insertValue(inDTO, "uDivCntGb", uDivCntGb);
			CallProFrame.insertValue(inDTO, "divisionId", aDivisionId);
			CallProFrame.callService("FS-DIS2", "DISMngResBrnDivCmpTotSO", "divTotSrch", inDTO, null,{'success' : getMngResDiv});
		
			function getMngResDiv(e) {
				var table1 = $('#' + idDiv);
				var xNo="";
				var cntNo=0;
				var lNo=0;
				var innerValue = "";
				
				var resArray = WebSquare.xml.findNodes(e.responseBody, "root/message/DISMngResDivOutputListDTO/mngResDivList");
				MngResXml = resArray;
				
				if (resArray.length > 0) {
					
					var a,b,c,d,e;
					
					for(var i=0;i<resArray.length;i++){					
						var hdLevel =  WebSquare.xml.getValue(resArray[i], "hdLevel");
						var parentDivId =  WebSquare.xml.getValue(resArray[i], "parentDivId");
						var divisionId =  WebSquare.xml.getValue(resArray[i], "divisionId");
						var divisionNm =  WebSquare.xml.getValue(resArray[i], "divisionNm");
						var uLastNodeYN =  WebSquare.xml.getValue(resArray[i], "uLastNodeYN");			
						var serviceDesc =  WebSquare.xml.getValue(resArray[i], "serviceDesc");			
						
						var onClick=' onClick="selectTd2(this,\''+idDiv+'Obj\',\''+parentDivId+'\',\''+divisionId+'\',\''+uLastNodeYN+'\',\''+divisionNm+'\')"'
						
						if(vPriPubGb=="11"){}else{onClick='';}	
											
						if(idDiv.substring(idDiv.length-1) == hdLevel){								
							if(hdLevel==1){
								innerValue +="<li style='' class=''><a class='' " + onClick + ">" + divisionNm + "</a></li>";
								
								xNo +=  i+ "|";							
								if(divisionId == uDivisionId1){									
									lNo = cntNo;
									uDivisionId1="";
									
									a = WebSquare.xml.getValue(resArray[i], "uLastNodeYN");		
									b = WebSquare.xml.getValue(resArray[i], "divisionId");		
									c = WebSquare.xml.getValue(resArray[i], "divisionNm");		
									d = WebSquare.xml.getValue(resArray[i], "serviceDesc");		
									e = parentDivId;
								}
								
								cntNo++;
							}
							
						}
					}
					
					table1.innerHTML = innerValue;
					
					var xx= WebSquare.util.getComponentById('divisionNm' + idDiv.substring(7));
					var yy= WebSquare.util.getComponentById('divisionId' + idDiv.substring(7));
					xx.setValue(c);
					yy.setValue(b);
					
					if(idDiv.substring(7)=="3"){
						parentDivId.setValue(e);
					}
					
					try {
						document.getElementById(idDiv+'Desc').innerText = d;
						document.getElementById(idDiv+'tit').innerHTML = "<b> ["+ c + "]</b>";	
					} catch(e) {var msg = e.message;}
					
					var num = eval(idDiv.substring(7))+1;					
					if(idDiv.substring(7)<3 && a =='N'){						
						xmlMngResDiv('tblList'+num,num,b);
					}	
					
				} else {
					innerValue = "";
										
					table1.innerHTML = innerValue;
					var table2 = document.getElementById("tblList2");
					var table3 = document.getElementById("tblList3");
					
					divisionNm1.setValue('');
					divisionNm2.setValue('');
					divisionNm3.setValue('');
					
					divisionId1.setValue('');
					divisionId2.setValue('');
					divisionId3.setValue('');
					
									
					document.getElementById("tblList1tit").innerHTML = "";
					document.getElementById("tblList1Desc").innerText = "";
					
					document.getElementById("tblList2tit").innerHTML = "";
					document.getElementById("tblList2Desc").innerText = "";
					
					document.getElementById("tblList3tit").innerHTML = "";
					document.getElementById("tblList3Desc").innerText = "";
					
					if(idDiv =="tblList1"){						
						table2.innerHTML = innerValue;						
						table3.innerHTML = innerValue;					
					}else if(idDiv=="tblList2"){						
						table3.innerHTML = innerValue;
					}		
					
				}
			}
		}
	    
	    function xmlMngResDiv(id,uDivCntGb,dvsId){	
			var resArray = MngResXml ;
			
			var table1 = $('#' + id);
			var innerValue='';
			var xNo="";
			var lNo=0;
			var cntNo=0;
			var a,b,c,d,e;
			
			if(resArray.length>0){				
				for(var i=0;i<resArray.length;i++){		
						var hdLevel =  WebSquare.xml.getValue(resArray[i], "hdLevel");
						var parentDivId =  WebSquare.xml.getValue(resArray[i], "parentDivId");
						var divisionId =  WebSquare.xml.getValue(resArray[i], "divisionId");
						var divisionNm =  WebSquare.xml.getValue(resArray[i], "divisionNm");
						var uLastNodeYN =  WebSquare.xml.getValue(resArray[i], "uLastNodeYN");			
						var serviceDesc =  WebSquare.xml.getValue(resArray[i], "serviceDesc");			
									
						if(vPriPubGb=="11"){}else{onClick='';}						
						if(uDivCntGb == hdLevel) {
							if(dvsId == parentDivId){		
								innerValue +="<li style='' class=''><a class='' " + onClick + ">" + divisionNm + "</a></li>";
								
								xNo+= i+"|";					
								var newDivision = eval("uDivisionId"+uDivCntGb);								
								if(divisionId == newDivision){									
									lNo = cntNo;
									newDivision="";
									
									a = WebSquare.xml.getValue(resArray[i], "uLastNodeYN");		
									b = WebSquare.xml.getValue(resArray[i], "divisionId");		
									c = WebSquare.xml.getValue(resArray[i], "divisionNm");		
									d = WebSquare.xml.getValue(resArray[i], "serviceDesc");		
									e = parentDivId;
								}
								cntNo++;
							}
						}
					}
					
					table1.innerHTML = innerValue;					
					
					
					var xx= WebSquare.util.getComponentById('divisionNm' + id.substring(7));
					var yy= WebSquare.util.getComponentById('divisionId' + id.substring(7));
					xx.setValue(c);
					yy.setValue(b);
					
					if(idDiv.substring(7)=="3"){
						parentDivId.setValue(e);
					}
					
					try {
						document.getElementById(idDiv+'Desc').innerText = d;
						document.getElementById(idDiv+'tit').innerHTML = "<b> ["+ c + "]</b>";	
					} catch(e) {var msg = e.message;}
					
					var num = eval(idDiv.substring(7))+1;					
					if(idDiv.substring(7)<3 && a =='N'){						
						xmlMngResDiv('tblList'+num,num,b);
					}	
			}else{
					innerValue="";
					table1.innerHTML = innerValue;
					
					var table2 = document.getElementById("tblList2");
					var table3 = document.getElementById("tblList3");
					
					if(id =="tblList1"){						
						table2.innerHTML = innerValue;						
						table3.innerHTML = innerValue;					
					}else if(id=="tblList2"){						
						table3.innerHTML = innerValue;
					}		
					
							
			}
		}
	    
	    
	    function radioCheck(){
			var year = uYear.getValue();
			var month = uMonth.getValue();
			
			var fundTyp = fundType.getValue();
			var amngScl = Imgradio1.getValue();
			
			ufundTyp.setValue(fundTyp);
			mngScl.setValue(amngScl);
