			}
				
		}
	    
	     /**************************************************************************
		 * function    : setFundGbComp
		 * Description : 집합투자업자 생성
		 * Parameter   : null
		 * Return      : null
		 **************************************************************************/
	    function setFundGbComp(callback) {
	    	var inDTO  = {"DISFundGbCompanyListDTO":{}}
	    	
			var standardYm = uYear.getValue() +""+ uMonth.getValue();
			var fundGb = ufundTyp.getValue();
			
			if(fundGb==""||fundGb==null){}else{
				CallProFrame.insertValue(inDTO, "fundGb", fundGb);
			} 
			
			CallProFrame.insertValue(inDTO, "standardYm", standardYm);
			CallProFrame.callService("FS-DIS2", "DISFundGbCompanySrchSO", "select", inDTO, null,{'success' : getFundGbComp});
			
			function getFundGbComp(e) {
				var select = companyCd;
				var gbCompArr = WebSquare.xml.findNodes(e.responseBody,'root/message/DISFundGbCompanyListDTO/list'); 
				
				for (var i=0; i < gbCompArr.length; i++) {
					var koreanNm = WebSquare.xml.getValue(gbCompArr[i] , 'koreanNm');
					var compCd = WebSquare.xml.getValue(gbCompArr[i] , 'companyCd');
					
					companyCd.addItem(compCd, koreanNm);
				}
				
				companyCd.setSelectedIndex(0);
				if (callback)
					callback();
			}
	    }

		/**************************************************************************
		 * function    : sendResult
		 * Description : 펀드수익률 비교공시 조건검색 실행
		 * Parameter   : null
		 * Return      : null
		 **************************************************************************/
		function sendResult(){
			var standardYm = uYear.getValue() +""+ uMonth.getValue() ;
			var vCompanyCd = companyCd.getValue();
			var companyNm = companyCd.getText();
			var vpriPubGb = priPubGb.getValue();
			var vpriPubGbNm = priPubGbNm.getValue();
			
			
			// 펀드유형
			var fundGb = fundType.getValue();
			// 운용규모 
			var mngScl = Imgradio1.getValue();
			//운용실적 1차 분류
			var vBranchCd1 = "";
			var vBranchNm1 = "";
			//운용실적 2차 분류 
			var vbranchNm2 = "";
			var vbranchCd2 = "";
			//운용실적 3차 분류
			var vbranchNm3 = "";
			var vbranchCd3 = "";
				
			var chkList = listCheck.getValue("|");
			var rateArea = new Array();
			rateArea = chkList.split("|");
			
			uCdList.setValue(chkList);
			
			var yearChkVal = uYear.getValue();
			var monthChkVal = uMonth.getValue();
			yearChkVal =  parseInt(yearChkVal, 10);
			monthChkVal = parseInt(monthChkVal, 10);
			
			if (radioBtn.getItemCount()==0)
			{
				alert("해당하는 운용분류실적이 없습니다.");
				return;
			}
			//운용실적 1차 분류
			vBranchCd1 = radioBtn.getValue();
			vBranchNm1 = radioBtn.getText();
			//운용실적 2차 분류 
			vbranchNm2 = vBranchNm2.getValue();
			vbranchCd2 = vBranchCd2.getValue();
			
			//운용실적 3차 분류
			vbranchNm3 = vBranchNm3.getValue();
			vbranchCd3 = vBranchCd3.getValue();
								
			if(rateArea.length == 4) {
				var postAct  = {};
								
				postAct.standardYm = standardYm;
				postAct.companyCd = vCompanyCd;
				postAct.priPubGb = vpriPubGb;
				postAct.priPubGbNm = vpriPubGbNm;
				postAct.fundGb = fundGb;
				postAct.mngScl = mngScl;
				postAct.uCdList = chkList;
				
				postAct.divisionId1 = vBranchCd1;
				postAct.divisionId2 = vbranchCd2;
				postAct.divisionId3 = vbranchCd3;
				postAct.fundGbNm = fundGbNm.getValue();
				postAct.divisionNm1 = vBranchNm1;
				postAct.divisionNm2 = vbranchNm2;
				postAct.divisionNm3 = vbranchNm3;
				
				
				postAct.PageNum = PageNum.getValue();
				postAct.parentDivId = parentDivId.getValue();
				var jsonParam = WebSquare.text.BASE64URLEncoder(JSONtoString(postAct));
	    	
		    	$frm = $('<form></form>');
				$frm.attr('action', menuLinkUrl + '?w2xPath=/wq/fundann/DISFundROPCmpAnnRes.xml' 
							+ '&' + $.param({'divisionId' : vDivisionId}) 
							+ '&' + $.param({'serviceId' : vServiceId}));
							
				$frm.attr('method', 'post');
				
				$frm.append('<input type="hidden" name="fundRopCmpAnnParams" id="fundRopCmpAnnParams" value="' + jsonParam + '" />');
				$frm.appendTo('body');
				$frm.submit();
				
			}else{
				alert("수익률 구간은 4개를 선택해야 합니다.");
			}
			
		}
		
